import{_ as e,o,c as a,a2 as i}from"./chunks/framework.BTaI8jHZ.js";const d=JSON.parse('{"title":"Tutorial: Your First GitHub Notification","description":"Connect a GitHub repository to a Matrix room and receive PR notifications","frontmatter":{"title":"Tutorial: Your First GitHub Notification","description":"Connect a GitHub repository to a Matrix room and receive PR notifications","audience":["user","operator"],"prereqs":["get-started/quickstart.md","integrations/github.md"],"time":"15 minutes"},"headers":[],"relativePath":"get-started/first-github-notification.md","filePath":"get-started/first-github-notification.md","lastUpdated":1775244379000}'),n={name:"get-started/first-github-notification.md"};function r(s,t,c,l,h,p){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="your-first-github-notification" tabindex="-1">Your First GitHub Notification <a class="header-anchor" href="#your-first-github-notification" aria-label="Permalink to &quot;Your First GitHub Notification&quot;">​</a></h1><p>Connect a GitHub repository to a Matrix room. When a pull request is opened, a notification appears in the room.</p><p><strong>Prerequisites:</strong></p><ul><li>A running hookshot instance with <a href="./../integrations/github#configuration">GitHub configured</a></li><li>A GitHub repository you have admin access to (for installing the GitHub App)</li></ul><h2 id="step-1-install-the-github-app" tabindex="-1">Step 1: Install the GitHub App <a class="header-anchor" href="#step-1-install-the-github-app" aria-label="Permalink to &quot;Step 1: Install the GitHub App&quot;">​</a></h2><p>If not already done, install the <a href="./../integrations/github#github-app-required">GitHub App</a> on your repository or organization. The App provides webhook delivery and API access.</p><p>See <a href="./../integrations/github#authentication">GitHub setup</a> for detailed instructions.</p><h2 id="step-2-authenticate-optional" tabindex="-1">Step 2: Authenticate (optional) <a class="header-anchor" href="#step-2-authenticate-optional" aria-label="Permalink to &quot;Step 2: Authenticate (optional)&quot;">​</a></h2><p>For commands that act as you (not required for receiving notifications):</p><p>DM the hookshot bot:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!github login</span></span></code></pre></div><p>Follow the OAuth link. See <a href="./../integrations/github#user-oauth-optional">GitHub authentication</a> for details.</p><p>Check status: <code>!github status</code></p><h2 id="step-3-connect-a-room-to-a-repository" tabindex="-1">Step 3: Connect a room to a repository <a class="header-anchor" href="#step-3-connect-a-room-to-a-repository" aria-label="Permalink to &quot;Step 3: Connect a room to a repository&quot;">​</a></h2><p>In your Matrix room:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!hookshot github repo https://github.com/your-org/your-repo</span></span></code></pre></div><p>Hookshot confirms the <a href="./../understand/integration-model">connection</a> was created. This writes a <a href="./../reference/event-types">room state event</a> (<code>uk.half-shot.matrix-hookshot.github.repository</code>).</p><p>Alternatively, use the <a href="./../integrations/github#setup">widget UI</a> or <a href="./../integrations/github#connection-options">provisioning API</a>.</p><h2 id="step-4-trigger-a-notification" tabindex="-1">Step 4: Trigger a notification <a class="header-anchor" href="#step-4-trigger-a-notification" aria-label="Permalink to &quot;Step 4: Trigger a notification&quot;">​</a></h2><p>Open a pull request on the connected repository. Within seconds, a message appears in the Matrix room:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>🔵 your-username opened a new PR your-org/your-repo#1: &quot;Your PR title&quot;</span></span></code></pre></div><p>This is hookshot&#39;s <a href="./../understand/event-lifecycle#inbound-external-service-to-matrix">inbound event flow</a> in action: GitHub webhook → signature verification → message queue → connection handler → Matrix message.</p><h2 id="step-5-try-a-command" tabindex="-1">Step 5: Try a command <a class="header-anchor" href="#step-5-try-a-command" aria-label="Permalink to &quot;Step 5: Try a command&quot;">​</a></h2><p>Create an issue from Matrix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>!gh create &quot;Test issue from Matrix&quot;</span></span></code></pre></div><p>Hookshot creates the issue on GitHub and confirms in the room. This is the <a href="./../understand/event-lifecycle#outbound-matrix-to-external-service">outbound flow</a>.</p><p>See all <a href="./../integrations/github#bot-commands">GitHub bot commands</a> or the full <a href="./../reference/bot-commands">bot commands reference</a>.</p><h2 id="step-6-try-emoji-reactions" tabindex="-1">Step 6: Try emoji reactions <a class="header-anchor" href="#step-6-try-emoji-reactions" aria-label="Permalink to &quot;Step 6: Try emoji reactions&quot;">​</a></h2><p>React to the PR notification message with 👍. Hookshot adds a thumbs-up reaction on the GitHub PR.</p><p>React with ✅ to approve the PR. See <a href="./../integrations/github#emoji-reactions">all emoji mappings</a>.</p><h2 id="what-you-learned" tabindex="-1">What you learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What you learned&quot;">​</a></h2><ul><li>GitHub integration uses a <a href="./../integrations/github#github-app-required">GitHub App</a> for webhooks and API access</li><li><a href="./../understand/integration-model">Connections</a> bind a Matrix room to a GitHub repo via <a href="./../reference/event-types">room state events</a></li><li>13 event types are <a href="./../integrations/github#supported-events">enabled by default</a>, including PRs, issues, and releases</li><li><a href="./../integrations/github#bot-commands">Bot commands</a> let you create issues and trigger workflows from Matrix</li><li><a href="./../integrations/github#emoji-reactions">Emoji reactions</a> map to GitHub actions</li></ul><h2 id="customizing" tabindex="-1">Customizing <a class="header-anchor" href="#customizing" aria-label="Permalink to &quot;Customizing&quot;">​</a></h2><ul><li><strong>Enable more events</strong> (e.g., <code>push</code>, <code>workflow.run</code>): Update the connection via widget or <a href="./../integrations/github#connection-options">connection options</a></li><li><strong>Filter by labels</strong>: Use <code>includingLabels</code> / <code>excludingLabels</code> in <a href="./../integrations/github#connection-options">connection options</a></li><li><strong>Change command prefix</strong>: Set <code>commandPrefix</code> in connection options (default: <code>!gh</code>)</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Solution</th></tr></thead><tbody><tr><td>No notification after PR</td><td>Check <a href="./../troubleshooting/webhooks-not-arriving">Webhooks Not Arriving</a></td></tr><tr><td>&quot;Not authorized&quot; on commands</td><td>Run <code>!github login</code> — see <a href="./../troubleshooting/authentication">Authentication troubleshooting</a></td></tr><tr><td>Can&#39;t connect repo</td><td>Check <a href="./../guides/operator/configuration#permissions">permissions</a> — need <code>manageConnections</code> level</td></tr><tr><td>Bot doesn&#39;t respond</td><td>See <a href="./../troubleshooting/connection-issues">Connection Issues</a></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../integrations/github">GitHub Integration</a> — Full reference with all 23 events, 6 connection types</li><li><a href="./../integrations/gitlab">GitLab Integration</a> — Similar setup for GitLab projects</li><li><a href="./../integrations/jira">JIRA Integration</a> — Bridge JIRA projects</li><li><a href="./../integrations/overview">Integration Overview</a> — All 8 services at a glance</li><li><a href="./../understand/event-lifecycle">Event Lifecycle</a> — Deep dive into event flow</li></ul>',38)])])}const g=e(n,[["render",r]]);export{d as __pageData,g as default};
